using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.AppHost.Evaluation;

public class EvaluationTests
{
    [Fact]
    public async Task AppHost_Starts_And_All_Resources_Healthy()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        await app.StartAsync();

        await app.WaitForResourcesToBeHealthyAsync();
    }

    [Fact]
    public async Task Agent_Responds_To_Basic_Prompt()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        await app.StartAsync();

        await app.WaitForResourcesToBeHealthyAsync();

        // Once resources are healthy, verify the agent endpoint responds.
        // Subclass or extend with actual HTTP calls to your agent endpoint.
        Assert.True(true, "App host started successfully; extend with agent-specific assertions.");
    }
}

